targets.expr:
sum by (method) (
  vertx_http_server_active_requests{
    kubernetes_namespace="$namespace",
    kubernetes_name="$service_name",
    instance=~"$pod_ip"
  }
)

sum by (method) (
  vertx_http_client_active_requests{
    kubernetes_namespace="$namespace",
    kubernetes_name="$service_name",
    instance=~"$pod_ip"
  }
)
